options.afterRender:
// Plays the camera picked in $camera: its HLS stream when it has one,
// otherwise its still image, reloaded every minute. The player is kept on
// `this` across renders, so a dashboard refresh does not restart the video:
// only another camera, or a re-rendered row, does.
const row = context.data || {};
// The row is as tall as its content by default: the player fills the panel.
context.element.style.height = '100%';
const box = context.element.querySelector('.cam-view');
const self = this;
const cleanup = () => setTimeout(() => {
  if (self.box && !self.box.isConnected && self.stop) {
    self.stop();
    self.stop = null;
    self.key = null;
  }
}, 0);
if (!box) {
  return cleanup;
}
const stream = row.stream_url;
const image = row.image_url;
const key = stream || image || '';
if (self.key === key && self.box === box && box.isConnected) {
  return cleanup;
}
if (self.stop) {
  self.stop();
}
self.key = key;
self.box = box;
self.stop = null;
box.replaceChildren();
const fill = 'width:100%;height:100%;object-fit:contain;background:#000;display:block';
let stopped = false;
let hls = null;
let video = null;
let timer = null;
const stopVideo = () => {
  const v = video;
  video = null;
  if (hls) {
    hls.destroy();
    hls = null;
  }
  if (v) {
    v.removeAttribute('src');
    v.load();
  }
};
self.stop = () => {
  stopped = true;
  stopVideo();
  clearInterval(timer);
};
// Caltrans' latest still, reloaded every minute: for a camera without video,
// and for one whose stream is down, which Caltrans goes on listing.
const still = (note) => {
  stopVideo();
  if (stopped) {
    return;
  }
  const status = context.element.querySelector('.cam-status');
  if (note && status) {
    status.textContent = note;
  }
  if (!image) {
    box.textContent = 'Caltrans publishes no image for this camera.';
    return;
  }
  const img = document.createElement('img');
  img.style.cssText = fill;
  box.replaceChildren(img);
  const load = () => {
    img.src = image + '?t=' + Date.now();
  };
  load();
  timer = setInterval(load, 60000);
};
if (!stream) {
  still();
  return cleanup;
}
const down = 'Stream down: the latest still image';
const el = document.createElement('video');
video = el;
el.muted = true;
el.autoplay = true;
el.playsInline = true;
el.controls = true;
el.style.cssText = fill;
if (image) {
  el.poster = image;
}
el.addEventListener('error', () => video === el && still(down));
box.append(el);
const play = () => el.play().catch(() => {});
if (el.canPlayType('application/vnd.apple.mpegurl')) {
  el.src = stream;
  play();
} else {
  import('https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.mjs')
    .then(({ default: Hls }) => {
      if (video !== el) {
        return;
      }
      if (!Hls.isSupported()) {
        still('This browser cannot play the stream: the latest still image');
        return;
      }
      hls = new Hls({ liveSyncDurationCount: 2 });
      hls.on(Hls.Events.ERROR, (_, data) => data.fatal && video === el && still(down));
      hls.loadSource(stream);
      hls.attachMedia(el);
      play();
    })
    .catch(() => video === el && still('The player did not load: the latest still image'));
}
return cleanup;

options.styles:
.cam { display: flex; flex-direction: column; height: 100%; gap: 6px; }
.cam-view { flex: 1; min-height: 0; background: #000; border-radius: 2px; overflow: hidden; display: flex; align-items: center; justify-content: center; color: #9AA5B1; }
.cam-caption { font-size: 12px; line-height: 1.4; color: #9AA5B1; }
.cam-caption strong { color: inherit; }
